janus2026 — swap (XOR):
// swap two values reversibly (C-style); ends with a clean store
void swap(int a, int b) {
    a ^= b;
    b ^= a;
    a ^= b;
}
void main() {
    int x = 0;
    int y = 0;
    x ^= 7;
    y ^= 11;
    printf("before: x=%d y=%d\n", x, y);
    call swap(x, y);
    printf("after:  x=%d y=%d\n", x, y);
    y ^= 7;     // restore the store to all-zero (no leftover values)
    x ^= 11;
}

janus2026 — counter (call/uncall):
// call / uncall reversibility: build a counter up, then undo it cleanly
void incr(int x) {
    x += 1;
}
void main() {
    int counter = 0;
    for (int k = 0; k < 5; k += 1) {
        call incr(counter);
    }
    printf("counter = %d\n", counter);
    for (int k = 0; k < 5; k += 1) {
        uncall incr(counter);    // restore counter = 0
    }
}
